import { readFileSync } from "node:fs";
import { startCloneProcess } from "/work/harness/src/clone-process.ts";
import { diff, blocking, PolicySchema } from "/work/harness/src/policy.ts";
import adapter from "/work/targets/stripe-billing/adapter.ts";
const policy = PolicySchema.parse(JSON.parse(readFileSync("/work/targets/stripe-billing/policy.json", "utf8")));
const port = 47000 + Math.floor(Math.random() * 1000);
const clone = await startCloneProcess("stripe-billing", "clone/server.ts", port);
const url = `http://127.0.0.1:${port}`;
const files = process.argv.slice(2);
let fails = 0;
for (const f of files) {
  const fx = JSON.parse(readFileSync(f, "utf8"));
  await fetch(url + "/__reset", { method: "POST" });
  const actual = await adapter.run({ id: fx.id, input: fx.input, rules: fx.rules } as any, { kind: "clone", url });
  const d = blocking(diff(policy, fx.observed, actual));
  if (d.length) { fails++; console.log("FAIL", fx.id); for (const x of d) console.log("  ", x.path, JSON.stringify(x.expected), "=>", JSON.stringify(x.actual)); }
  if (process.env.DUMP) console.log(JSON.stringify(actual, null, 1));
}
console.log("done", files.length, "fails", fails);
await (clone as any).stop?.();
process.exit(0);
EOF
